@Test
public void testStore() throws Exception {
    // Write results to a new file
    File outFile = createFile("test2.properties");
    OutputStream out = new FileOutputStream(outFile);
    m_props.store(out, null);
    out.close();
    // Load the file into new props object; should return identical strings
    Properties props2 = new CommentedProperties();
    InputStream in = CommentedPropertiesTest.class.getClassLoader().getResourceAsStream("test2.properties");
    props2.load(in);
    in.close();
    Assert.assertEquals(m_props.toString(), props2.toString());
    // Remove props1, 2, 3 & resave props to new file
    m_props.remove("testProp1");
    m_props.remove("testProp2");
    m_props.remove("testProp3");
    outFile = createFile("test3.properties");
    out = new FileOutputStream(outFile);
    m_props.store(out, null);
    out.close();
    // Load the new file; should not have props1/2/3 & is shorter
    Properties props3 = new CommentedProperties();
    in = CommentedPropertiesTest.class.getClassLoader().getResourceAsStream("test3.properties");
    props3.load(in);
    in.close();
    Assert.assertNotSame(m_props.toString(), props3.toString());
    Assert.assertFalse(props3.containsKey("testProp1"));
    Assert.assertFalse(props3.containsKey("testProp2"));
    Assert.assertFalse(props3.containsKey("testProp3"));
    Assert.assertTrue(props3.containsKey("testProp4"));
    Assert.assertTrue(props3.containsKey("testProp5"));
    // Clean up
    File file = getFile("test2.properties");
    if (file != null && file.exists()) {
        file.delete();
    }
    file = getFile("test3.properties");
    if (file != null && file.exists()) {
        file.delete();
    }
}

@Test
public void testCharOrder() {
    HumanComparator comparator = new HumanComparator();
    // Default order first
    Assert.assertTrue(comparator.compare("a c", "a1c") < 0);
    Assert.assertTrue(comparator.compare("a1c", "abc") < 0);
    // Now letters then numbers then other
    HumanComparator.CharType[] sortOrder = { HumanComparator.CharType.TYPE_LETTER, HumanComparator.CharType.TYPE_DIGIT, HumanComparator.CharType.TYPE_OTHER };
    comparator.setSortOrder(sortOrder);
    Assert.assertTrue(comparator.compare("a c", "a1c") > 0);
    Assert.assertTrue(comparator.compare("a1c", "abc") > 0);
    // Now numbers then letters then other
    sortOrder[0] = HumanComparator.CharType.TYPE_DIGIT;
    sortOrder[1] = HumanComparator.CharType.TYPE_LETTER;
    sortOrder[2] = HumanComparator.CharType.TYPE_OTHER;
    comparator.setSortOrder(sortOrder);
    Assert.assertTrue(comparator.compare("a c", "a1c") > 0);
    Assert.assertTrue(comparator.compare("a1c", "abc") < 0);
    // Finally try to break it
    try {
        sortOrder[0] = HumanComparator.CharType.TYPE_DIGIT;
        sortOrder[1] = HumanComparator.CharType.TYPE_DIGIT;
        sortOrder[2] = HumanComparator.CharType.TYPE_OTHER;
        comparator.setSortOrder(sortOrder);
        Assert.fail("Expected IllegalArgumentException");
    } catch (IllegalArgumentException e) {
        // All worked
    }
}

@Test
public void testCompare() {
    Comparator<String> comparator = new HumanComparator();
    Assert.assertTrue(comparator.compare("abcd001", "ABCD001") > 0);
    Assert.assertTrue(comparator.compare("abcd001a", "ABCD001z") < 0);
    Assert.assertTrue(comparator.compare("abc8", "abcd1") < 0);
    Assert.assertTrue(comparator.compare("abc 8", "abc1") < 0);
    Assert.assertTrue(comparator.compare("abc  8", "abc 1") < 0);
    Assert.assertTrue(comparator.compare("abdc001", "ABCD001") > 0);
    Assert.assertTrue(comparator.compare("ab cd001", "ABDC001") < 0);
    Assert.assertTrue(comparator.compare("10", "01") > 0);
    Assert.assertTrue(comparator.compare("10", "00000001") > 0);
    Assert.assertTrue(comparator.compare("01", "00000001") < 0);
}

