    PriorityList<String> p = new PriorityList<String>();
    p.add("One", 1);
    p.add("Two", 2);
    p.add("Three", 3);
    Assert.assertEquals("size", 3, p.size());
    Assert.assertEquals("Three", "Three", p.get(0));
    Assert.assertEquals("Two", "Two", p.get(1));
    Assert.assertEquals("One", "One", p.get(2));
