    elements = XmlUtil.parse(is, "/modules/editor");
    Assert.assertEquals(0, elements.size());
    elements = XmlUtil.parse(is, "/modules/heck");
    Assert.assertEquals(0, elements.size());
    elements = XmlUtil.parse((InputStream) null, "/modules/editor");
    Assert.assertEquals(0, elements.size());
